-- Вопросы раздела «17. Собеседование DBA» с пояснениями к каждому варианту. Требует миграции 019.
-- Повторный запуск безопасен: вопрос с тем же текстом не добавляется второй раз.

BEGIN;

INSERT INTO questions (category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM (
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Чем физическая резервная копия отличается от логической (дампа)?', '{"A":"Разницы нет, это два названия одного и того же","B":"Физическая — копия файлов кластера и журналов WAL, логическая — команды SQL для воссоздания объектов","C":"Логическая копия всегда быстрее восстанавливается","D":"Физическая копия делается только при остановленном сервере"}'::jsonb, 'B', 'Дамп делают pg_dump и pg_dumpall, физическую копию — pg_basebackup или низкоуровневым копированием.', '{"A":"Это принципиально разные механизмы.","B":"Поэтому физическая восстанавливается быстро, а при наличии архива WAL — и на любой момент после окончания её создания; логическая гибче.","C":"Наоборот: при восстановлении из дампа выполняются все команды, включая построение индексов.","D":"Физическую копию можно снять и на работающем сервере, например pg_basebackup."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Нужно перенести одну базу на сервер с другой основной версией PostgreSQL. Что подходит?', '{"A":"Дамп pg_dump","B":"Копирование каталога базы из PGDATA/base","C":"Физическая реплика","D":"Базовая копия pg_basebackup"}'::jsonb, 'A', 'Для обновления основной версии используют также pg_upgrade и логическую репликацию.', '{"A":"Для команд SQL двоичная совместимость не нужна.","B":"Файлы одной базы без остального кластера и журнала не восстановить.","C":"Физическая репликация требует той же основной версии.","D":"Физическая копия восстанавливается только на той же основной версии и архитектуре, к тому же только целиком."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Мешает ли работающий pg_dump другим сеансам?', '{"A":"Никак не мешает, блокировок не берёт","B":"Чтение и изменение данных не блокируются, но DROP TABLE и большинство форм ALTER TABLE для выгружаемых таблиц будут ждать","C":"Блокирует всю базу на запись до конца выгрузки","D":"Останавливает автоочистку во всём кластере"}'::jsonb, 'B', 'Дамп отражает состояние базы на момент начала выгрузки, так как читается один снимок данных.', '{"A":"Блокировки ACCESS SHARE конфликтуют с командами, которым нужна ACCESS EXCLUSIVE.","B":"pg_dump берёт блокировки ACCESS SHARE и держит их до конца выгрузки.","C":"Изменять данные можно: pg_dump читает согласованный снимок.","D":"Автоочистку он не останавливает, хотя его долгая транзакция удерживает горизонт очистки."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Чем горячее резервное копирование отличается от холодного?', '{"A":"Горячее копирование возможно только для логических копий","B":"Горячее делается на работающем сервере, и для восстановления нужны журналы WAL за время копирования","C":"Горячее делается при остановленном сервере","D":"Холодная копия всегда требует архива журналов"}'::jsonb, 'B', 'Холодная копия проще, но требует остановки сервера.', '{"A":"Физическая копия тоже снимается горячей, например pg_basebackup.","B":"Скопированные файлы несогласованны, согласованность восстанавливается по журналу.","C":"Это холодное копирование.","D":"Копия аккуратно остановленного сервера согласованна и журналов не требует."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Как в PostgreSQL 16 называется функция начала низкоуровневого резервного копирования (раньше pg_start_backup)?', '{"A":"`pg_begin_backup`","B":"`pg_basebackup`","C":"`pg_start_backup`","D":"`pg_backup_start`"}'::jsonb, 'D', 'Завершает копирование функция pg_backup_stop.', '{"A":"Такой функции нет.","B":"Это отдельная утилита, а не функция SQL.","C":"В PostgreSQL 15 её переименовали в pg_backup_start и одновременно удалили монопольный режим копирования.","D":"Функции переименованы в версии 15: pg_backup_start и pg_backup_stop."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что делает в PostgreSQL команда ALTER DATABASE … BEGIN BACKUP?', '{"A":"Такой команды в PostgreSQL нет, это синтаксис Oracle","B":"Запрещает запись в базу до конца копирования","C":"Создаёт базовую копию в каталоге по умолчанию","D":"Переводит базу в режим горячего копирования"}'::jsonb, 'A', 'Копирование выполняется для всего кластера, а не для отдельной базы.', '{"A":"В PostgreSQL низкоуровневое копирование начинают функцией pg_backup_start.","B":"Такой команды в PostgreSQL нет, а горячее копирование запись не запрещает.","C":"Такой команды нет; базовую копию создаёт pg_basebackup.","D":"Так эта команда работает в Oracle, в PostgreSQL её нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', '{"A":"Между вызовами нельзя подключаться к серверу","B":"Сеанс, вызвавший pg_backup_start, должен оставаться открытым до pg_backup_stop","C":"Сервер нужно перевести в режим только для чтения","D":"pg_backup_stop можно вызвать из любого другого сеанса"}'::jsonb, 'B', 'pg_backup_stop возвращает содержимое файла backup_label, его нужно сохранить вместе с копией.', '{"A":"Ограничения на подключения нет.","B":"Если соединение прервётся, копирование будет отменено.","C":"Сервер продолжает работать как обычно.","D":"Копирование не монопольное и привязано к сеансу, который его начал."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', '{"A":"`now()`","B":"`''immediate''`","C":"`false`","D":"`true`"}'::jsonb, 'D', 'Немедленная контрольная точка создаёт всплеск записи на диск.', '{"A":"Параметр логического типа, время не подходит.","B":"Параметр логического типа, такое значение не подходит.","C":"Это значение по умолчанию: контрольная точка растягивается и копирование начнётся позже.","D":"Контрольная точка выполняется сразу, а не растягивается во времени."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', '{"A":"Только базовая копия","B":"Базовая копия и непрерывный архив WAL от её начала до нужного момента","C":"Только архив WAL","D":"Только дамп pg_dump"}'::jsonb, 'B', 'Целевая точка задаётся параметрами recovery_target_*.', '{"A":"Без архива журналов автономная копия восстанавливается только на момент окончания её создания.","B":"Журнал применяется к копии до целевой точки.","C":"Журналы применяются к базовой копии, без неё их не к чему применить.","D":"Дамп восстанавливается только на момент его создания."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```', '{"A":"`archive_timeout`","B":"`recovery_min_apply_delay`","C":"`restore_command`","D":"`recovery_target_time`"}'::jsonb, 'D', 'Есть также recovery_target_xid, recovery_target_lsn и recovery_target_name.', '{"A":"Задаёт принудительное переключение сегментов для архивации.","B":"Задаёт задержку применения журнала на реплике.","C":"Задаёт команду получения сегментов из архива.","D":"Задаёт момент времени, до которого применяется журнал."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', '{"A":"Приостанавливает восстановление, чтобы можно было проверить данные","B":"Удаляет архив журналов","C":"Продолжает применять журнал до конца архива","D":"Сразу становится обычным сервером"}'::jsonb, 'A', 'Продолжить работу после проверки можно функцией pg_wal_replay_resume().', '{"A":"Это значение pause параметра recovery_target_action; без hot_standby оно работает как shutdown.","B":"Архив сервер не трогает.","C":"Целевая точка как раз останавливает применение.","D":"Так ведёт себя значение promote, оно не по умолчанию."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', '{"A":"Нет: целевая точка должна быть после окончания копирования, нужна более ранняя копия","B":"Да, если указать recovery_target_lsn","C":"Да, но только для отдельной базы","D":"Да, на любой момент из архива"}'::jsonb, 'A', 'Поэтому базовые копии делают регулярно и хранят несколько.', '{"A":"Раньше этого момента копия ещё несогласованна.","B":"Способ задания цели не меняет этого ограничения.","C":"Физическое восстановление выполняется для всего кластера.","D":"Журнал проигрывается вперёд от начала копии, а остановиться можно только после достижения согласованности."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите запрос, чтобы посчитать долю попаданий в буферный кеш (buffer hit ratio) по базам:
```
SELECT datname,
       round(100.0 * blks_hit / nullif(blks_hit + ___, 0), 2) AS hit_ratio
FROM pg_stat_database;
```', '{"A":"`temp_bytes`","B":"`xact_commit`","C":"`blks_read`","D":"`tup_returned`"}'::jsonb, 'C', 'Для OLTP обычно ожидают долю около 99%.', '{"A":"Это объём временных файлов.","B":"Это число зафиксированных транзакций.","C":"Число блоков, которых не было в буферном кеше и которые пришлось читать.","D":"Это число строк, а не блоков."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', '{"A":"Счётчик сбрасывается каждую секунду","B":"Блоки из blks_read могли быть взяты из кеша операционной системы","C":"blks_read учитывает только временные файлы","D":"buffer hit ratio всегда равен 100%"}'::jsonb, 'B', 'Реальные чтения с диска смотрят средствами ОС или по pg_stat_io.', '{"A":"Счётчики накопительные до сброса статистики.","B":"PostgreSQL не знает, читала ли ОС блок с диска или из своего кеша.","C":"Он считает чтения блоков данных, не найденных в буферном кеше.","D":"Нет, он зависит от нагрузки и размера кеша."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Чем опасны сеансы в состоянии idle in transaction?', '{"A":"Они автоматически откатываются через минуту","B":"Они ничем не опасны","C":"Они потребляют много процессорного времени","D":"Они удерживают блокировки и могут удерживать горизонт очистки"}'::jsonb, 'D', 'Найти их можно в pg_stat_activity по state.', '{"A":"По умолчанию не откатываются; для этого есть idle_in_transaction_session_timeout.","B":"Это частая причина разрастания таблиц и ожиданий блокировок.","C":"Бездействующий сеанс процессор почти не нагружает.","D":"Таблицы растут, а другие сеансы ждут блокировок."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какие системы используют для мониторинга PostgreSQL?', '{"A":"pg_upgrade","B":"Zabbix","C":"Prometheus с postgres_exporter","D":"pgbench"}'::jsonb, 'BC', 'В курсе упоминаются также PoWA и pg_profile; журнал анализируют pgBadger.', '{"A":"Это утилита обновления основной версии.","B":"Есть готовые шаблоны для PostgreSQL.","C":"Экспортёр отдаёт метрики из представлений статистики.","D":"Это утилита нагрузочного тестирования."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какая функция показывает, какие процессы блокируют данный процесс?', '{"A":"`pg_blocking_pids(pid)`","B":"`pg_cancel_backend(pid)`","C":"`pg_stat_reset()`","D":"`pg_backend_pid()`"}'::jsonb, 'A', 'Сами блокировки видны в представлении pg_locks.', '{"A":"Возвращает массив номеров процессов, которые его блокируют.","B":"Эта функция отменяет запрос процесса.","C":"Сбрасывает счётчики статистики.","D":"Возвращает номер своего процесса."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какое значение synchronous_commit гарантирует, что после фиксации изменения уже видны запросам на синхронной реплике?', '{"A":"`local`","B":"`remote_apply`","C":"`on`","D":"`remote_write`"}'::jsonb, 'B', 'Чем строже режим, тем медленнее фиксация.', '{"A":"Реплику не ждёт вообще.","B":"Фиксация ждёт, пока реплика применит записи.","C":"Ждёт только сохранения записей на диске реплики, применение может отставать.","D":"Ждёт только передачи записей операционной системе реплики."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', '{"A":"Реплика получила записи и передала их ОС, но на диск они ещё могут быть не сброшены","B":"Реплику не ждут","C":"Записи сброшены на диск реплики","D":"Записи применены на реплике"}'::jsonb, 'A', 'Режим быстрее on, но немного менее надёжен.', '{"A":"Данные переживут сбой PostgreSQL на реплике, но не сбой её ОС.","B":"Это значения local и off.","C":"Это значение on.","D":"Это значение remote_apply."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что будет при synchronous_commit = off и сбое сервера?', '{"A":"Могут потеряться последние подтверждённые транзакции, но согласованность базы не нарушится","B":"Сервер не запустится без восстановления из копии","C":"Ничего не потеряется","D":"База может быть повреждена"}'::jsonb, 'A', 'Окно потерь — до трёх значений wal_writer_delay.', '{"A":"Фиксация не ждёт записи журнала на диск.","B":"Сервер восстановится по журналу как обычно.","C":"Последние транзакции могут не успеть попасть на диск.","D":"Повреждения не будет: журнал записывается в правильном порядке."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', '{"A":"`remote_apply`","B":"`remote_write`","C":"`local`","D":"`on`"}'::jsonb, 'ABD', 'При пустом synchronous_standby_names реплику не ждёт ни одно значение.', '{"A":"Ждёт применения записей на реплике.","B":"Ждёт передачи записей ОС реплики.","C":"Ждёт только локальной записи журнала.","D":"Ждёт сохранения на диске реплики."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите команду, чтобы не ждать записи журнала только для текущей транзакции:
```
BEGIN;
SET ___ synchronous_commit = off;
```', '{"A":"`TRANSACTION`","B":"`SESSION`","C":"`GLOBAL`","D":"`LOCAL`"}'::jsonb, 'D', 'Так ускоряют некритичные транзакции, не меняя настройку для всех.', '{"A":"Команда SET TRANSACTION задаёт характеристики транзакции, а не параметры.","B":"Значение будет действовать до конца сеанса, если транзакция будет зафиксирована.","C":"Такого ключевого слова в SET нет.","D":"Значение действует до конца текущей транзакции."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что верно для свойств ACID?', '{"A":"Стойкость: зафиксированные изменения переживают сбой","B":"Атомарность: изменения транзакции применяются целиком или не применяются вовсе","C":"Согласованность: данные на всех репликах одинаковы","D":"Изолированность: транзакции всегда выполняются строго по очереди"}'::jsonb, 'AB', 'Согласованность означает переход базы из одного корректного состояния в другое.', '{"A":"Это обеспечивает журнал предзаписи.","B":"Частично выполненной транзакции не бывает.","C":"Речь о соблюдении ограничений целостности в одной базе, а не о репликах.","D":"Транзакции выполняются параллельно, а уровень изоляции определяет, какие аномалии допустимы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какой механизм обеспечивает стойкость (D в ACID) в PostgreSQL?', '{"A":"Буферный кеш","B":"Запись грязных буферов при каждой фиксации","C":"Автоочистка","D":"Запись журнала WAL на диск при фиксации"}'::jsonb, 'D', 'Именно поэтому synchronous_commit = off ослабляет стойкость.', '{"A":"Он в оперативной памяти и при сбое теряется.","B":"Буферы пишутся независимо от фиксации: при контрольной точке, фоновой записью или при вытеснении.","C":"Она удаляет неактуальные версии строк.","D":"После сбоя изменения восстанавливаются по журналу."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', '{"A":"Таблица останется, но будет пустой","B":"Её не будет: CREATE TABLE, как и большинство команд DDL в PostgreSQL, транзакционна","C":"Таблица останется, откатятся только данные","D":"Транзакция не начнётся: DDL нельзя выполнять в транзакции"}'::jsonb, 'B', 'Исключения есть, например CREATE DATABASE.', '{"A":"Таблица не будет создана вовсе.","B":"Это отличает PostgreSQL от многих других СУБД.","C":"Создание таблицы тоже откатывается.","D":"Большинство команд DDL можно."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Какую команду нельзя выполнить внутри блока транзакции?', '{"A":"`CREATE DATABASE`","B":"`TRUNCATE`","C":"`ALTER TABLE`","D":"`CREATE TABLE`"}'::jsonb, 'A', 'Вне явного блока транзакции выполняются также VACUUM и CREATE INDEX CONCURRENTLY.', '{"A":"Её нельзя выполнить внутри явного блока транзакции.","B":"В PostgreSQL она транзакционна.","C":"Большинство её форм можно выполнить и откатить; исключение — DETACH PARTITION CONCURRENTLY.","D":"Её можно выполнить и откатить."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', '{"A":"Обычно нет: место станет свободным внутри файла, ОС вернётся только пустой хвост файла","B":"Да, сразу после DELETE","C":"Да, после следующей контрольной точки","D":"Да, всегда после VACUUM"}'::jsonb, 'A', 'Вернуть место ОС можно VACUUM FULL или перезаписью таблицы.', '{"A":"Освобождённое место используют новые строки этой таблицы.","B":"DELETE только помечает версии строк как удалённые.","C":"Контрольная точка на размер файлов не влияет.","D":"VACUUM возвращает ОС только пустые страницы в конце файла."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Что нужно учитывать, запуская VACUUM FULL для большой таблицы?', '{"A":"Дополнительное место на диске не нужно","B":"Таблица полностью блокируется, и нужно свободное место для её новой копии","C":"Индексы после него нужно перестроить вручную","D":"Таблица остаётся доступной на запись"}'::jsonb, 'B', 'Без долгой блокировки таблицы место возвращает расширение pg_repack.', '{"A":"Новая копия создаётся рядом со старой.","B":"Таблица и индексы перезаписываются заново.","C":"Индексы перестраиваются автоматически.","D":"Берётся блокировка ACCESS EXCLUSIVE, недоступно даже чтение."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Как быстрее всего освободить место, если удалить нужно все строки таблицы?', '{"A":"Выполнить DELETE без условия","B":"Выполнить TRUNCATE","C":"Выполнить CHECKPOINT","D":"Выполнить DELETE и ANALYZE"}'::jsonb, 'B', 'TRUNCATE берёт блокировку ACCESS EXCLUSIVE, но работает быстро.', '{"A":"Строки станут мёртвыми, но место на диске не освободится.","B":"Файлы таблицы заменяются пустыми, место освобождается сразу после фиксации.","C":"Контрольная точка место не освобождает.","D":"ANALYZE обновляет статистику, а не место на диске."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Чем общий план подготовленного оператора отличается от частного?', '{"A":"Частный строится с учётом конкретных значений параметров, общий — без них и используется повторно","B":"Частный план хранится на диске","C":"Разницы нет","D":"Общий план строится для всех баз кластера"}'::jsonb, 'A', 'Режимом управляет параметр plan_cache_mode.', '{"A":"Общий план экономит время планирования, частный учитывает значения параметров и может оказаться эффективнее.","B":"Планы хранятся в памяти сеанса.","C":"Для неравномерных данных планы могут сильно различаться.","D":"План относится к оператору в сеансе, а не к базам."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', '{"A":"После ANALYZE таблицы","B":"После пяти выполнений с частными планами, если общий план не намного дороже их средней стоимости","C":"Сразу при первом выполнении","D":"Никогда"}'::jsonb, 'B', 'Если общий план выбран неудачно, помогает force_custom_plan.', '{"A":"ANALYZE лишь делает план недействительным для перестроения.","B":"Иначе продолжают строиться частные планы.","C":"Первые пять выполнений используют частные планы.","D":"Переход возможен после пяти выполнений."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите команду, чтобы подготовленные операторы с параметрами всегда строили частный план:
```
SET plan_cache_mode = ___;
```', '{"A":"`force_custom_plan`","B":"`auto`","C":"`custom`","D":"`force_generic_plan`"}'::jsonb, 'A', 'Параметр можно задать для сеанса, роли или функции.', '{"A":"План строится заново с учётом значений параметров.","B":"Это значение по умолчанию, выбор делает сервер.","C":"Такого значения нет.","D":"Всегда используется общий план."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Как в штатном режиме обновляется статистика для планировщика?', '{"A":"При каждой контрольной точке","B":"Только вручную командой ANALYZE","C":"Автоочистка выполняет ANALYZE, когда изменилось достаточно строк таблицы","D":"При каждом выполнении запроса"}'::jsonb, 'C', 'Статистика хранится в pg_statistic, удобно смотреть её в pg_stats.', '{"A":"Контрольная точка со статистикой не связана.","B":"Обычно её запускает автоочистка.","C":"Порог задают autovacuum_analyze_threshold и autovacuum_analyze_scale_factor.","D":"Статистика собирается выборочно командой ANALYZE."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Зачем нужна команда CREATE STATISTICS?', '{"A":"Посмотреть статистику по таблице","B":"Собирать расширенную статистику по нескольким столбцам, например их зависимость","C":"Включить сбор статистики для таблицы","D":"Сбросить накопительную статистику"}'::jsonb, 'B', 'Расширенную статистику собирает ANALYZE, без него она пуста.', '{"A":"Для этого есть pg_stats и представления pg_stat_*.","B":"Обычная статистика считает столбцы независимыми и ошибается для связанных.","C":"Обычная статистика собирается и без неё.","D":"Для этого есть функции pg_stat_reset*."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '17.'), 'Допишите команду, чтобы после ANALYZE планировщик учитывал зависимость почтового индекса от города:
```
CREATE STATISTICS addr_stats (___) ON city, zip FROM addresses;
```', '{"A":"`ndistinct`","B":"`histogram`","C":"`correlation`","D":"`dependencies`"}'::jsonb, 'D', 'Есть также вид mcv — частые сочетания значений.', '{"A":"Тоже вид расширенной статистики, но он считает число различных сочетаний значений.","B":"Такого вида расширенной статистики нет.","C":"Такого вида расширенной статистики нет.","D":"Функциональные зависимости между столбцами."}'::jsonb
) AS n(category_id, question_text, options, correct_answer, explanation, option_notes)
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NOT NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('17.'));
    IF n < 35 THEN
        RAISE EXCEPTION 'Ожидалось не меньше 35 вопросов с пояснениями в темах 17–17, найдено %', n;
    END IF;
END
$check$;

COMMIT;
